package org.eclipse.rdf4j.sail.lmdb.evaluation.codegen;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.sail.lmdb.LmdbQueryMemoryManager;
import org.eclipse.rdf4j.sail.lmdb.evaluation.codegen.KernelResultCoordinates.Transport;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.EnumSource;

class KernelResultCoordinateRepresentationsTest {

	@ParameterizedTest
	@EnumSource(value = Transport.class, names = { "DENSE", "CHANGES", "SELECTION" })
	void copiedWindowsPreserveAliasesUnboundCellsFramesAndBackwardsReads(Transport transport) {
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(1_000_000L, 1_000_000L);
		try (LmdbQueryMemoryManager.QueryLedger ledger = manager.openQuery();
				KernelResultCoordinates coordinates = KernelResultCoordinates.open(ledger, 64,
						new int[] { 2, 0, 2, 1, 63, -1 }, new int[] { 0, 3, 5, 9, 63, -1 },
						7L | Long.MIN_VALUE, 64, 1, transport)) {
			assertThat(coordinates).isNotNull();
			long a = coordinates.newNamespace();
			long b = coordinates.newNamespace();
			int frame = coordinates.newFrame();
			long[][][] expected = new long[64][6][];
			for (int row = 0; row < 64; row++) {
				long namespace = row < 32 ? a : b;
				long[] first = { 10L, 20L, row / 8, 30L, namespace };
				coordinates.set(0, first[0], first[1], first[2], first[3], first[4]);
				if (row == 48) {
					coordinates.restore(frame, 1L);
					first = new long[] { 10L, 20L, 0L, 30L, a };
				}
				if (row % 7 == 0) {
					coordinates.clear(1);
				} else {
					coordinates.set(1, 11L, 21L, row % 3, 31L, a);
					expected[row][3] = new long[] { 11L, 21L, row % 3, 31L, a };
				}
				if (row % 5 == 0) {
					coordinates.clear(2);
				} else {
					coordinates.copy(2, 0);
					expected[row][0] = first;
					expected[row][2] = first;
				}
				coordinates.set(63, 99L, 98L, row / 16, 97L, b);
				expected[row][1] = first;
				expected[row][4] = new long[] { 99L, 98L, row / 16, 97L, b };
				if (row == 0) {
					coordinates.save(frame);
				}
				coordinates.emit();
			}
			assertThat(coordinates.enabled()).isTrue();
			assertThat(coordinates.changedSlots(0)).isEqualTo(1L | 1L << 3 | 1L << 5 | 1L << 9 | Long.MIN_VALUE);
			coordinates.requestRetirement(a);
			coordinates.requestRetirement(b);
			coordinates.clearMask(-1L);
			coordinates.releaseFrame(frame);
			List<Long> retired = new ArrayList<>();
			coordinates.drainRetiredNamespaces(retired::add);
			assertThat(retired).isEmpty();

			long[] copied = new long[KernelResultCoordinates.WIDTH];
			for (int ordinal = 0; ordinal < 64; ordinal++) {
				int row = ordinal * 37 & 63;
				for (int output = 5; output >= 0; output--) {
					long[] cell = expected[row][output];
					assertThat(coordinates.hasCoordinate(row, output)).isEqualTo(cell != null);
					assertThat(coordinates.coordinate(row, output, copied)).isEqualTo(cell != null);
					if (cell != null) {
						assertThat(copied).containsExactly(cell);
					}
				}
				coordinates.releaseRow(row);
				assertThat(coordinates.hasCoordinate(row, 1)).isFalse();
				coordinates.drainRetiredNamespaces(retired::add);
				if (ordinal < 63) {
					assertThat(retired).isEmpty();
				}
			}
			assertThat(retired).containsExactlyInAnyOrder(a, b);

			coordinates.beginFill();
			long next = coordinates.newNamespace();
			coordinates.set(1, 101L, 102L, 103L, 104L, next);
			coordinates.emit();
			assertThat(coordinates.hasCoordinate(0, 0)).isFalse();
			assertThat(coordinates.hasCoordinate(0, 1)).isFalse();
			assertThat(coordinates.hasCoordinate(0, 4)).isFalse();
			assertThat(coordinates.coordinate(0, 3, copied)).isTrue();
			assertThat(copied).containsExactly(101L, 102L, 103L, 104L, next);
			coordinates.clear(1);
			coordinates.requestRetirement(next);
			coordinates.releaseRow(0);
			coordinates.drainRetiredNamespaces(retired::add);
			assertThat(retired).containsExactlyInAnyOrder(a, b, next);
		}
		assertThat(manager.usedBytes()).isZero();
	}

	@ParameterizedTest
	@EnumSource(value = Transport.class, names = { "CHANGES", "SELECTION" })
	void recordGrowthRefusalWithdrawsCoordinatesAndReleasesEveryReservation(Transport transport) {
		long budget = 1_000_000L;
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(budget, budget);
		try (LmdbQueryMemoryManager.QueryLedger ledger = manager.openQuery();
				KernelResultCoordinates coordinates = KernelResultCoordinates.open(ledger, 1,
						new int[] { 0 }, new int[] { 0 }, 1L, 128, 0, transport)) {
			assertThat(coordinates).isNotNull();
			long namespace = coordinates.newNamespace();
			for (int row = 0; row < 8; row++) {
				coordinates.set(0, 3L, 4L, row, 0L, namespace);
				coordinates.emit();
			}
			try (LmdbQueryMemoryManager.Reservation blocker = ledger.tryReserveWithoutReclamation(
					budget - ledger.usedBytes())) {
				assertThat(blocker).isNotNull();
				long full = ledger.usedBytes();
				coordinates.set(0, 3L, 4L, 8L, 0L, namespace);
				coordinates.emit();
				assertThat(coordinates.enabled()).isFalse();
				assertThat(coordinates.coordinate(0, 0, new long[KernelResultCoordinates.WIDTH])).isFalse();
				assertThat(ledger.usedBytes()).isEqualTo(full);
				List<Long> retired = new ArrayList<>();
				coordinates.drainRetiredNamespaces(retired::add);
				assertThat(retired).containsExactly(namespace);
			}
			coordinates.close();
			assertThat(ledger.usedBytes()).isZero();
		}
		assertThat(manager.usedBytes()).isZero();
	}

	@Test
	void compactRepresentationsAdmitLessMetadataForRepeatedWideRows() {
		long dense = repeatedWindowBytes(Transport.DENSE);
		assertThat(repeatedWindowBytes(Transport.CHANGES)).isLessThan(dense / 8);
		assertThat(repeatedWindowBytes(Transport.SELECTION)).isLessThan(dense / 4);
	}

	@Test
	void offDoesNotAcquireCoordinateMemory() {
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(1_000_000L, 1_000_000L);
		try (LmdbQueryMemoryManager.QueryLedger ledger = manager.openQuery()) {
			assertThat(KernelResultCoordinates.open(ledger, 1, new int[] { 0 }, new int[] { 0 }, 1L,
					128, 0, Transport.OFF)).isNull();
			assertThat(ledger.usedBytes()).isZero();
		}
	}

	private static long repeatedWindowBytes(Transport transport) {
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(1_000_000L, 1_000_000L);
		int[] outputs = new int[12];
		for (int i = 0; i < outputs.length; i++) {
			outputs[i] = i;
		}
		long bytes;
		try (LmdbQueryMemoryManager.QueryLedger ledger = manager.openQuery();
				KernelResultCoordinates coordinates = KernelResultCoordinates.open(ledger, 12, outputs, outputs,
						(1L << 12) - 1L, 256, 0, transport)) {
			assertThat(coordinates).isNotNull();
			long namespace = coordinates.newNamespace();
			for (int column = 0; column < outputs.length; column++) {
				coordinates.set(column, 1L, 2L, 3L, column, namespace);
			}
			for (int row = 0; row < 256; row++) {
				coordinates.emit();
			}
			bytes = ledger.usedBytes();
			assertThat(coordinates.enabled()).isTrue();
		}
		assertThat(manager.usedBytes()).isZero();
		return bytes;
	}
}
